def decode(encoded: str, original: str, message: str) -> str:
    """
    Builds a mapping from each character in `encoded` to the corresponding
    character in `original` and decodes `message` using that mapping.
    If the mapping contains a contradiction or does not cover all 26
    uppercase letters, the function returns "Failed".
    """
    # Basic sanity check: encoded and original must be the same length
    if len(encoded) != len(original):
        return "Failed"

    # Build mapping, check for contradictions
    mapping = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"  # contradiction
        else:
            mapping[e_char] = o_char

    # Ensure all 26 uppercase letters are present in mapping
    if len(mapping) < 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"  # unmapped character
        decoded_chars.append(mapping[ch])

    return ''.join(decoded_chars)

def generate_numbers(n, rules) -> int:
    """Generate all unique numbers reachable from the original integer n by repeatedly
    applying digit transformation rules.

    Parameters
    ----------
    n : int
        The original number.
    rules : list of tuple[int, int]
        Each tuple (x, y) indicates that digit x can be transformed into y.

    Returns
    -------
    int
        The count of unique numbers that can be generated, including n itself.
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    # Build mapping from digit to list of possible replacements
    mapping = {}
    for rule in rules:
        if not isinstance(rule, tuple) or len(rule) != 2:
            raise ValueError("Each rule must be a tuple of two integers")
        x, y = rule
        if not (isinstance(x, int) and isinstance(y, int)):
            raise ValueError("Rule elements must be integers")
        mapping.setdefault(x, []).append(y)

    visited = {n}
    queue = [n]
    while queue:
        current = queue.pop(0)
        s = str(current)
        for i, ch in enumerate(s):
            d = int(ch)
            if d in mapping:
                for y in mapping[d]:
                    new_s = s[:i] + str(y) + s[i+1:]
                    new_num = int(new_s)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    import re

    # Regular expressions for the 4 supported statement forms
    patterns = [
        re.compile(r'^(?P<subject>\w+)\s+is\s+guilty\.$', re.IGNORECASE),
        re.compile(r'^(?P<subject>\w+)\s+is\s+not guilty\.$', re.IGNORECASE),
        re.compile(r'^I\s+am\s+guilty\.$', re.IGNORECASE),
        re.compile(r'^I\s+am\s+not guilty\.$', re.IGNORECASE)
    ]

    # Helper to determine if a statement references a weekday
    day_lower = {day.lower() for day in days_of_week}
    def contains_weekday(statement: str) -> bool:
        lowered = statement.lower()
        return any(day in lowered for day in day_lower)

    for speaker, stmts in statements.items():
        if not isinstance(stmts, list):
            continue  # skip malformed entries
        for stmt in stmts:
            if not isinstance(stmt, str):
                continue
            if contains_weekday(stmt):
                continue  # ignore statements about the day of the week
            stmt = stmt.strip()
            truth = None
            for pattern in patterns:
                match = pattern.match(stmt)
                if match:
                    if pattern.pattern == r'^(?P<subject>\w+)\s+is\s+guilty\.$':
                        subject = match.group('subject')
                    elif pattern.pattern == r'^(?P<subject>\w+)\s+is\s+not guilty\.$':
                        subject = match.group('subject')
                        subject = subject  # still subject string
                    elif pattern.pattern == r'^I\s+am\s+guilty\.$':
                        subject = speaker
                    elif pattern.pattern == r'^I\s+am\s+not guilty\.$':
                        subject = speaker
                    else:
                        continue  # should not happen

                    if pattern.pattern in [r'^(?P<subject>\w+)\s+is\s+guilty\.$', r'^I\s+am\s+guilty\.$']:
                        truth = (subject == scenario)
                    else:  # "is not guilty" or "I am not guilty"
                        truth = (subject != scenario)
                    break  # stop after first matching pattern

            if truth is None:
                # Statement does not match any supported pattern; ignore it
                continue

            # Verify truthfulness against liar status
            if speaker in liar_count:
                if truth:  # liars should be lying; truth must be False
                    return False
            else:
                if not truth:  # truth-tellers must say true statements
                    return False

    return True

